(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.03+t*0.5)*8 + Math.cos((y+w1y)*0.025-t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.028-t*0.45)*8 + Math.sin((x+w1x)*0.022+t*0.55)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*40, 0.09, 1.8],
    [200+Math.sin(t*0.7+5)*110, 220+Math.cos(t*0.3+3)*30, 0.08, 2.4],
    [300+Math.cos(t*0.42+2)*90, 40+Math.sin(t*0.58+1)*60, 0.1, 2.0]
  ];
  let aS = 0, iS = 0, iS2 = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    iS2 += Math.sin(d*f*1.3 - t*sp*0.4 + 3.0);
  }
  const act = aS/10, inh = iS/10, inh2 = iS2/10;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1) + Math.sin(sx*0.06+sy*0.02-t*1.5))/3
    + Math.sin((sx+sy)*0.12+t*2.5)*0.15 + Math.sin((sx-sy)*0.1-t*2)*0.15 + Math.sin(sx*0.08-t*1.8)*0.1;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cx, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2) + Math.sin(dist*0.07-ang*2+t*0.8))*0.3;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.15;
  const reaction = Math.tanh((act - inh*0.5 - inh2*0.3 + bg*0.25 + spiral + cell*0.2 + micro)*2.0);
  const reaction2 = Math.tanh((inh*0.8 - act*0.4 + bg*0.5 + spiral*0.6)*1.5);
  const blend = reaction*0.65 + reaction2*0.2 + cell*0.15;
  const v = blend*0.5+0.5;
  const pal = [[6,12,52],[10,40,85],[15,75,115],[20,120,130],[40,165,135],[130,195,100],[220,195,70],[235,145,60],[200,85,55],[140,45,65],[75,25,60],[35,15,55],[6,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85 + Math.sin(reaction*Math.PI)*0.15;
  const edge = Math.abs(reaction)>0.65?1.12:Math.abs(reaction2)>0.6?1.06:1.0;
  const vig = 1.0 - Math.sqrt((x-cx)**2+(y-cy)**2)/400*0.15;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*vig)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*vig)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*vig)|0
  ];
}
